\title{A Sharp Tensor-Product Certificate for Parallel Residual Blocks}
\author{Aristotle}
\date{25 August 2026}

\begin{document}
\maketitle

\begin{abstract}
We develop the algebra of Lipschitz certificates for residual blocks --- maps of the form $F(x) = x + r(x)$ on a real (semi)normed space, where the residual $r$ is $K$-Lipschitz --- in the cartesian monoidal category of real normed spaces and Lipschitz maps. Our central result is that the monoidal (parallel) product of two residual blocks with certificates $K_1$ and $K_2$ is a residual block with certificate $\max(K_1,K_2)$, hence Lipschitz with constant $\max(1+K_1,1+K_2)$ for the max product norm; and that this bound is \emph{attained} for every pair $K_1,K_2 \ge 0$, in the strongest available sense: the set of valid Lipschitz constants of an explicit parallel pair of blocks has $\max(1+K_1,1+K_2)$ as its least element. We prove moreover that the max rule is \emph{minimal} --- any rule assigning valid parallel certificates dominates it pointwise --- and that the sharp constant is \emph{independent of the cartesian structure}, being simultaneously optimal in the $\ell^\infty$, $\ell^1$ and $\ell^2$ products. Serial composition obeys $K_1 \sser K_2 = K_1+K_2+K_1K_2$, so that $K \mapsto 1+K$ is an order isomorphism of the certificate monoid onto the multiplicative gain monoid $([1,\infty),\times)$, with $\sser$ distributing over $\max$: the positive part of the max-times tropical semiring. Finally we quantify the \emph{laxity defect}: the interchange law holds exactly on maps, but only as an inequality on certificates, and for the alternating width-two architecture at depth $2n$ the sharp and layerwise gains are exactly $2^n$ and $4^n$, so the defect is unbounded even with all certificates in $\{0,1\}$. We close with the dual theory: certificates $K<1$ force bi-Lipschitz invertibility, and inverse certificates obey the same max rule, sharply.
\end{abstract}

\noindent\textbf{Keywords:} residual block, Lipschitz certificate, monoidal category, lax monoidal functor, product norm, tropical semiring, interchange law, bi-Lipschitz invertibility.

\section{Introduction}

\subsection{Motivation}

The residual parametrisation $F(x) = x + r(x)$ has a clean mathematical reading independent of any learning context: it is a \emph{perturbation of the identity}. If the perturbation $r$ is $K$-Lipschitz, the perturbed map inherits stability from the identity, degraded by a controlled amount:
\[
\|F(x)-F(y)\| \le \|x-y\| + \|r(x)-r(y)\| \le (1+K)\|x-y\|.
\]
We call $K$ the block's \textbf{certificate} and $1+K$ its \textbf{gain}.

Lipschitz constants of composite maps are the currency of a great deal of applied analysis: robustness to perturbation, well-posedness of inverse problems, stability of iterative schemes, contraction analysis, and generalization bounds. In all these settings one begins with per-component constants and must assemble a constant for the whole. That assembly is governed by an algebra, and this paper works out the algebra completely for residual blocks in the cartesian monoidal setting, with attention to \emph{sharpness} (is the assembled constant attained?) and \emph{coherence} (does it depend on the order of assembly?).

\subsection{Results}

\begin{enumerate}
\item \textbf{Gain bound.} A block with certificate $K$ is $(1+K)$-Lipschitz (Proposition~\ref{prop:gain}).
\item \textbf{Serial rule.} Composition gives certificate $K_1 \sser K_2 := K_1+K_2+K_1K_2$; gains multiply (Theorem~\ref{thm:serial}).
\item \textbf{Parallel rule.} The parallel product has certificate $\max(K_1,K_2)$, hence gain $\max(1+K_1,1+K_2)$ (Theorem~\ref{thm:par}).
\item \textbf{Attainment.} That gain is the \emph{least} Lipschitz constant of an explicit pair (Theorem~\ref{thm:attain}).
\item \textbf{Minimality.} Any valid parallel rule dominates $\max$ pointwise (Theorem~\ref{thm:minimal}).
\item \textbf{Metric independence.} The same sharp constant in $\ell^\infty$, $\ell^1$, $\ell^2$ (Theorem~\ref{thm:pind}).
\item \textbf{Width and depth.} Sharp gains $\sup_i(1+K_i)$ and $(1+K)^d$, with the relaxation $\exp(\max(K_1d_1,K_2d_2))$ (Section~\ref{sec:widthdepth}).
\item \textbf{Laxity.} Interchange holds on maps but not on certificates; the defect is $2^n$ versus $4^n$ at depth $2n$, hence unbounded (Section~\ref{sec:lax}).
\item \textbf{Dual theory.} $K<1$ forces bijectivity with $(1-K)^{-1}$-Lipschitz inverse, and inverse certificates obey the same sharp max rule (Section~\ref{sec:inv}).
\end{enumerate}

\subsection{Conventions}

$X,Y$ denote real seminormed additive commutative groups. Certificates lie in $\Rnn = [0,\infty)$. On a product the default metric is the \textbf{max product metric}
\[
d\big((x,y),(x',y')\big) = \max\big(d(x,x'),\,d(y,y')\big),
\]
the standard product-of-metric-spaces structure. Section~\ref{sec:pind} treats $\ell^1$ and $\ell^2$. For maps $f,g$ we write $f\times g$ for $(x,y)\mapsto(f(x),g(y))$.

\section{The certificate semiring}

\begin{definition}
For $a,b\in\Rnn$ set $a \sser b := a+b+ab$ (\emph{serial}), $a \ppar b := \max(a,b)$ (\emph{parallel}), and $\gamma(a) := 1+a$ (the \emph{gain}).
\end{definition}

\begin{proposition}\label{prop:gainmul}
$\gamma(a\sser b) = \gamma(a)\gamma(b)$, i.e.\ $1+(a+b+ab) = (1+a)(1+b)$; and $\gamma(a\ppar b) = \max(\gamma(a),\gamma(b))$.
\end{proposition}

\begin{proof}
The first is an expansion; the second holds because translation is order preserving.
\end{proof}

\begin{theorem}\label{thm:structure}
$(\Rnn,\sser,0)$ is a commutative monoid, $(\Rnn,\ppar,0)$ is an idempotent commutative monoid, and $\sser$ distributes over $\ppar$:
\[
(a\ppar b)\sser c = (a\sser c)\ppar(b\sser c).
\]
Moreover $\gamma$ is an order isomorphism of $\Rnn$ onto $[1,\infty)$ carrying $(\sser,\ppar)$ to $(\times,\max)$; in particular it is an injective monoid homomorphism $(\Rnn,\sser,0)\to(\Rnn,\times,1)$.
\end{theorem}

\begin{proof}
Associativity, commutativity and unitality of $\sser$ are polynomial identities (or follow from Proposition~\ref{prop:gainmul} and injectivity of $\gamma$); the corresponding facts for $\ppar$ are properties of $\max$. For distributivity, $\sser$ is monotone in each argument, so if $a\le b$ both sides equal $b\sser c$, and symmetrically. Finally $\gamma$ is a strictly increasing bijection onto $[1,\infty)$ with inverse $g\mapsto g-1$.
\end{proof}

Thus the certificate calculus is the positive part of the \textbf{max-times tropical semiring}: gains in $[1,\infty)$ with $\oplus = \max$ and $\otimes = \times$.

\begin{remark}\label{rem:mono}
$a\le b$ and $c\le d$ imply $a \sser c \le b\sser d$, and $\sser$ is strictly monotone in each argument.
\end{remark}

\section{Residual blocks}

\begin{definition}
A \textbf{residual block on $X$ with certificate $K$} is a $K$-Lipschitz map $r:X\to X$; the block \emph{computes} $B(x):=x+r(x)$. The \emph{identity block} has $r\equiv0$ and certificate $0$.
\end{definition}

\begin{proposition}\label{prop:gain}
A residual block with certificate $K$ computes a $(1+K)$-Lipschitz map.
\end{proposition}

\begin{proof}
The identity is $1$-Lipschitz, $r$ is $K$-Lipschitz, and sums of Lipschitz maps into a seminormed group add constants.
\end{proof}

\begin{definition}\label{def:dil}
For $K\ge0$ the \textbf{dilation block} on $\mathbb R$ has $r(x)=Kx$. Its certificate is exactly $K$, and it computes $x\mapsto(1+K)x$.
\end{definition}

\begin{definition}
For blocks $B_1$ (certificate $K_1$, residual $r_1$) and $B_2$ (certificate $K_2$, residual $r_2$) on $X$, the \textbf{serial composition} $B_2\circ B_1$ is the block with residual $r(x) := r_1(x) + r_2\big(x+r_1(x)\big)$.
\end{definition}

\begin{theorem}\label{thm:serial}
$B_2\circ B_1$ is a residual block with certificate $K_1\sser K_2$, and it computes the composite of the two maps. Hence gains multiply.
\end{theorem}

\begin{proof}
$r$ is the sum of a $K_1$-Lipschitz map and the composite of a $K_2$-Lipschitz map with a $(1+K_1)$-Lipschitz map, hence $K_1+K_2(1+K_1) = K_1\sser K_2$-Lipschitz. And $x + r(x) = (x+r_1(x)) + r_2(x+r_1(x)) = B_2(B_1(x))$.
\end{proof}

\begin{corollary}\label{cor:depth}
The $d$-fold iterate of a block of certificate $K$ is $(1+K)^d$-Lipschitz; for the dilation block it is $x\mapsto(1+K)^dx$.
\end{corollary}

\section{The tensor-product certificate}

\begin{definition}
The \textbf{parallel composition} of blocks $B_1$ on $X$ and $B_2$ on $Y$ is the block on $X\times Y$ with residual $r_1\times r_2$.
\end{definition}

\begin{theorem}[Tensor-product certificate; upper bound]\label{thm:par}
The parallel composition of blocks with certificates $K_1,K_2$ is a residual block on $X\times Y$ with certificate $\max(K_1,K_2)$. Consequently, for all $p,q\in X\times Y$,
\[
d\big((B_1\times B_2)(p),(B_1\times B_2)(q)\big) \le \max(1+K_1,\,1+K_2)\, d(p,q).
\]
\end{theorem}

\begin{proof}
Put $M=\max(K_1,K_2)$ and $p=(x,y)$, $q=(x',y')$. Then
\[
d\big((r_1\times r_2)p,(r_1\times r_2)q\big) = \max\big(d(r_1x,r_1x'), d(r_2y,r_2y')\big) \le \max\big(K_1 d(x,x'), K_2 d(y,y')\big) \le M\, d(p,q),
\]
so the parallel residual is $M$-Lipschitz. Proposition~\ref{prop:gain} and Proposition~\ref{prop:gainmul} give the gain $1+M = \max(1+K_1,1+K_2)$.
\end{proof}

\begin{lemma}[Sharpness for linear dilations]\label{lem:sharp}
For $a,b\ge0$ the map $D_{a,b}:(x,y)\mapsto(ax,by)$ on $\mathbb R^2$ with the max product metric has least Lipschitz constant exactly $\max(a,b)$.
\end{lemma}

\begin{proof}
Validity is the estimate in Theorem~\ref{thm:par}. For the lower bound, test $p=(1,0)$, $q=(0,0)$: input distance $1$, output distance $a$, so $a\le L$ for any valid $L$; and $p=(0,1)$, $q=(0,0)$ gives $b \le L$.
\end{proof}

\begin{remark}\label{rem:coord}
The extremisers are the coordinate directions: in the max product metric a single-coordinate perturbation costs exactly what it costs in the factor. This is the property that survives the change of product metric in Section~\ref{sec:pind}.
\end{remark}

\begin{theorem}[Attainment]\label{thm:attain}
For every $K_1,K_2 \ge 0$, the parallel composition of the dilation blocks with these certificates computes $(x,y)\mapsto\big((1+K_1)x,(1+K_2)y\big)$, whose least Lipschitz constant is exactly $\max(1+K_1,1+K_2)$.
\end{theorem}

\begin{proof}
Definition~\ref{def:dil} and Lemma~\ref{lem:sharp} with $a = 1+K_1$, $b = 1+K_2$.
\end{proof}

\begin{theorem}[Minimality of the max rule]\label{thm:minimal}
Let $c:\Rnn\times\Rnn\to\Rnn$ be such that for all $K_1,K_2$ and all residual blocks $B_1,B_2$ on $\mathbb R$ with those certificates, $B_1\times B_2$ is $(1+c(K_1,K_2))$-Lipschitz. Then $\max(K_1,K_2)\le c(K_1,K_2)$ for all $K_1,K_2$.
\end{theorem}

\begin{proof}
Apply the hypothesis to the dilation blocks: $1+c(K_1,K_2)$ is a valid constant for the map of Theorem~\ref{thm:attain}, whose least valid constant is $1+\max(K_1,K_2)$. Cancel the $1$.
\end{proof}

\section{Independence of the cartesian structure}\label{sec:pind}

For $p\in[1,\infty]$ write $X\times_p Y$ for $X\times Y$ with
\[
d_p\big((x,y),(x',y')\big) = \big(d(x,x')^p + d(y,y')^p\big)^{1/p}\quad (p<\infty), \qquad d_\infty = \max.
\]

\begin{theorem}\label{thm:l1}
If $f$ is $a$-Lipschitz and $g$ is $b$-Lipschitz then $f\times g$ is $\max(a,b)$-Lipschitz on $X\times_1 Y$.
\end{theorem}

\begin{proof}
With $M=\max(a,b)$: $d(fx,fx') + d(gy,gy') \le a\,d(x,x') + b\,d(y,y') \le M\big(d(x,x') + d(y,y')\big)$.
\end{proof}

\begin{theorem}\label{thm:l2}
Under the same hypotheses, $f\times g$ is $\max(a,b)$-Lipschitz on $X\times_2 Y$.
\end{theorem}

\begin{proof}
The coordinatewise bounds give $d(fx,fx')^2 + d(gy,gy')^2 \le M^2\big(d(x,x')^2 + d(y,y')^2\big)$; take square roots, using $\sqrt{M^2t} = M\sqrt t$ for $M\ge0$.
\end{proof}

\begin{theorem}\label{thm:lpattain}
For $a,b\ge0$ and $p\in\{1,2\}$, the map $(x,y)\mapsto(ax,by)$ on $\mathbb R\times_p\mathbb R$ has least Lipschitz constant exactly $\max(a,b)$.
\end{theorem}

\begin{proof}
Upper bounds are Theorems~\ref{thm:l1} and \ref{thm:l2}. For the lower bound test on $\big((1,0),(0,0)\big)$ and $\big((0,1),(0,0)\big)$: in each case exactly one coordinate difference is nonzero, and the $p$-combination of a single nonzero entry is that entry, so the input distance is $1$ and the output distance is $a$ (resp.\ $b$), for every $p$.
\end{proof}

\begin{theorem}[Metric independence]\label{thm:pind}
For all $K_1,K_2\ge0$, the number $\max(1+K_1,1+K_2)$ is simultaneously the least Lipschitz constant of the parallel pair of dilation blocks in $\mathbb R\times_\infty\mathbb R$, $\mathbb R\times_1\mathbb R$ and $\mathbb R\times_2\mathbb R$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:attain} for $p=\infty$; Theorem~\ref{thm:lpattain} with $a=1+K_1$, $b=1+K_2$ otherwise.
\end{proof}

As Remark~\ref{rem:coord} anticipated, the mechanism is that the extremisers are supported in a single coordinate, where all $\ell^p$ combinations agree; only that normalisation is used, so the statement holds for every $p\in[1,\infty]$. The tensor-product certificate is an invariant of the pair of blocks, not of the gluing.

\section{Width and depth}\label{sec:widthdepth}

\begin{theorem}\label{thm:wide}
Let $I$ be finite and $f_i:X_i\to X_i$ be $K_i$-Lipschitz. Then $(x_i)_i\mapsto(f_i(x_i))_i$ is $(\sup_i K_i)$-Lipschitz for the sup product metric. Consequently a family of blocks with certificates $K_i$ assembles into a block with certificate $\sup_i K_i$ and gain $\sup_i(1+K_i)$ (for nonempty $I$).
\end{theorem}

\begin{proof}
$d(f_ix_i,f_iy_i)\le K_i d(x_i,y_i)\le (\sup_j K_j) d(x,y)$; take the supremum over $i$. The gain identity $1+\sup_i K_i = \sup_i (1+K_i)$ follows by induction from $1+\max(a,b)=\max(1+a,1+b)$.
\end{proof}

\begin{theorem}[Sharpness in every width]\label{thm:widesharp}
For finite $I$ and $a:I\to\Rnn$, the map $x\mapsto(a_ix_i)_i$ on $\mathbb R^I$ with the sup metric has least Lipschitz constant $\sup_i a_i$.
\end{theorem}

\begin{proof}
Validity is Theorem~\ref{thm:wide}. For the lower bound test the $j$-th coordinate vector against $0$: input distance $1$, output distance at least $a_j$.
\end{proof}

\begin{theorem}[Sharpness in depth]\label{thm:depthsharp}
The $d$-fold iterate of the dilation block with certificate $K$ is $x\mapsto(1+K)^dx$, of least Lipschitz constant exactly $(1+K)^d$.
\end{theorem}

\begin{proof}
The formula is an induction from $B(x)=(1+K)x$; test $x=1$, $y=0$ for the lower bound.
\end{proof}

\begin{theorem}[Parallel stacks]\label{thm:stacks}
For blocks with certificates $K_1,K_2$ and depths $d_1,d_2$, the parallel pair of stacks is $\max\big((1+K_1)^{d_1},(1+K_2)^{d_2}\big)$-Lipschitz, and for dilation blocks this constant is least. Moreover
\[
\max\big((1+K_1)^{d_1},(1+K_2)^{d_2}\big) \le \exp\big(\max(K_1d_1,\,K_2d_2)\big).
\]
\end{theorem}

\begin{proof}
Combine Corollary~\ref{cor:depth} with the parallel estimate of Theorem~\ref{thm:par}; sharpness is Lemma~\ref{lem:sharp} applied to $a=(1+K_1)^{d_1}$, $b=(1+K_2)^{d_2}$ using Theorem~\ref{thm:depthsharp}. The relaxation follows from $1+t\le e^t$, whence $(1+K)^d\le e^{Kd}$, and monotonicity of $\exp$.
\end{proof}

\section{Laxity: the same map, two certificates}\label{sec:lax}

\begin{theorem}[Interchange on maps]\label{thm:interchange}
For blocks $B_1,C_1$ on $X$ and $B_2,C_2$ on $Y$,
\[
(B_1\times B_2)\circ(C_1\times C_2) = (B_1\circ C_1)\times(B_2\circ C_2),
\]
as maps and indeed as residual blocks.
\end{theorem}

\begin{proof}
Both sides send $(x,y)$ to $\big(B_1(C_1(x)), B_2(C_2(y))\big)$.
\end{proof}

\begin{theorem}[Interchange on certificates is only an inequality]\label{thm:laxineq}
For all $a,b,c,d\ge0$,
\[
(a\sser c)\ppar(b\sser d) \le (a\ppar b)\sser(c\ppar d),
\]
and the inequality can be strict: with $a=0,b=1,c=1,d=0$ the left side is $1$ and the right side is $3$; in gains, $2$ versus $4$.
\end{theorem}

\begin{proof}
Both $a\sser c$ and $b\sser d$ are dominated by the right side by Remark~\ref{rem:mono}, hence so is their max. The witness is a direct computation.
\end{proof}

\begin{theorem}[Equality when the second stage is shared]
$(a\sser c)\ppar(b\sser c) = (a\ppar b)\sser c$.
\end{theorem}

\begin{proof}
Distributivity, Theorem~\ref{thm:structure}.
\end{proof}

\begin{theorem}[Laxity realised by genuine maps]\label{thm:laxmaps}
Take, in stream one, the identity block followed by the dilation block of certificate $1$; in stream two, the dilation block of certificate $1$ followed by the identity block. The composite map is $(x,y)\mapsto(2x,2y)$, of least Lipschitz constant $2$, while the layerwise calculus certifies $(0\ppar1)\sser(1\ppar0) = 3$, i.e.\ gain $4$.
\end{theorem}

\begin{proof}
Each stream computes $t\mapsto 2t$ by Theorem~\ref{thm:serial}; apply Lemma~\ref{lem:sharp} with $a=b=2$, and Theorem~\ref{thm:laxineq} for the certificate.
\end{proof}

\begin{definition}
For width-two branch certificates $a_j,b_j$, $j = 0,\dots,d-1$, set
\[
\sharpg(d) := \max\Big(\prod_{j<d}(1+a_j),\ \prod_{j<d}(1+b_j)\Big), \qquad
\coarseg(d) := \prod_{j<d}\max\big(1+a_j,\,1+b_j\big).
\]
\end{definition}

\begin{theorem}[Both valid; sharp is the truth]\label{thm:sharpcoarse}
$\sharpg(d)$ and $\coarseg(d)$ are both valid Lipschitz constants of the parallel pair of stacks, and $\sharpg(d)\le\coarseg(d)$. For parallel dilation stacks, $\sharpg(d)$ is the \emph{least} Lipschitz constant.
\end{theorem}

\begin{proof}
Validity of $\sharpg$: each stream has gain $\prod_j(1+a_j)$ by Theorem~\ref{thm:serial}, and the parallel rule takes the max. Validity of $\coarseg$: certify each layer by Theorem~\ref{thm:par} and compose by Theorem~\ref{thm:serial}. The inequality is termwise. Sharpness: the dilation stack computes $x\mapsto\big(\prod_j(1+a_j)\big)x$, so Lemma~\ref{lem:sharp} applies.
\end{proof}

\begin{theorem}[The alternating architecture]\label{thm:alt}
Let $a_j = 1$ for even $j$ and $0$ for odd $j$, and $b_j = 0$ for even $j$ and $1$ for odd $j$. Then $\sharpg(2n) = 2^n$ and $\coarseg(2n) = 4^n$.
\end{theorem}

\begin{proof}
By induction on $n$: over each consecutive pair of layers each stream's product doubles, so both branch products equal $2^n$ and their max is $2^n$. Every layer has $\max(1+a_j,1+b_j) = 2$, so $\coarseg(2n) = 2^{2n} = 4^n$.
\end{proof}

\begin{theorem}[Unbounded laxity defect]\label{thm:unbounded}
For every $M\ge0$ there is $n$ with $M\cdot\sharpg(2n)\le\coarseg(2n)$ for the alternating architecture; equivalently the over-estimation ratio $\coarseg/\sharpg = 2^n$ is unbounded in the depth, even though all certificates lie in $\{0,1\}$.
\end{theorem}

\begin{proof}
Choose $n$ with $2^n\ge M$; then $M\cdot2^n\le 2^n2^n = 4^n$, and Theorem~\ref{thm:alt} identifies the sides.
\end{proof}

\subsection{A tropical reading}

Arrange the gains $g_{ij} = 1+K_{ij}$ in a $w\times d$ matrix. Then
\[
\sharpg = \bigoplus_i\bigotimes_j g_{ij} = \max_i\prod_j g_{ij}, \qquad \coarseg = \bigotimes_j\bigoplus_i g_{ij} = \prod_j\max_i g_{ij},
\]
with $\oplus = \max$, $\otimes = \times$. The laxity defect is the failure of the two contraction orders to agree. The viewpoint predicts the extremal configurations: permutation-like supports, in which each layer's largest certificate sits in a different stream, so the maxima charged layer by layer are never all collected by any single stream. The alternating architecture is the width-two instance.

\subsection{Practical consequence}

The two schemes have identical cost and the depth-first one is exponentially tighter: accumulate along streams and take maxima once, at the end.

\section{The dual theory: contractive blocks and inverses}\label{sec:inv}

\begin{theorem}\label{thm:anti}
A residual block on a normed space with certificate $K<1$ is antilipschitz with constant $(1-K)^{-1}$, i.e.\ $\|x-y\|\le(1-K)^{-1}\|B(x)-B(y)\|$; in particular it is injective.
\end{theorem}

\begin{proof}
$\|B(x)-B(y)\|\ge\|x-y\| - \|r(x)-r(y)\|\ge(1-K)\|x-y\|$.
\end{proof}

\begin{theorem}\label{thm:surj}
If $X$ is complete and $K<1$, then $B$ is surjective.
\end{theorem}

\begin{proof}
Fix $y$. The map $\Phi(x) = y - r(x)$ is a $K$-contraction on a nonempty complete space, so has a fixed point $x^\ast = y - r(x^\ast)$; then $B(x^\ast) = y$.
\end{proof}

\begin{theorem}\label{thm:bilip}
On a complete space, a residual block with certificate $K<1$ computes a bijection whose inverse is $(1-K)^{-1}$-Lipschitz.
\end{theorem}

\begin{proof}
Bijectivity is Theorems~\ref{thm:anti} and~\ref{thm:surj}; apply the antilipschitz bound at $x = B^{-1}(u)$, $y = B^{-1}(v)$.
\end{proof}

\begin{lemma}\label{lem:invmax}
For $a,b<1$, $\big(1-\max(a,b)\big)^{-1} = \max\big((1-a)^{-1},(1-b)^{-1}\big)$.
\end{lemma}

\begin{proof}
$t\mapsto(1-t)^{-1}$ is increasing on $[0,1)$, and increasing maps commute with $\max$.
\end{proof}

\begin{theorem}[Dual max rule]\label{thm:dual}
Let $X,Y$ be complete and $B_1,B_2$ have certificates $K_1,K_2<1$. Then $B_1\times B_2$ is a bijection of $X\times Y$ with inverse Lipschitz constant
\[
\big(1-\max(K_1,K_2)\big)^{-1} = \max\big((1-K_1)^{-1},(1-K_2)^{-1}\big).
\]
\end{theorem}

\begin{proof}
The parallel block has certificate $\max(K_1,K_2)<1$ (Theorem~\ref{thm:par}); apply Theorem~\ref{thm:bilip} and Lemma~\ref{lem:invmax}.
\end{proof}

\begin{definition}
For $0\le K<1$ the \textbf{inward dilation block} has residual $r(x) = -Kx$; its certificate is exactly $K$ and it computes $x\mapsto(1-K)x$, with inverse $y\mapsto(1-K)^{-1}y$.
\end{definition}

\begin{theorem}[Sharpness of the dual rule]\label{thm:dualsharp}
For $K_1,K_2<1$ the inverse of the parallel product of inward dilation blocks is $(u,v)\mapsto\big((1-K_1)^{-1}u,(1-K_2)^{-1}v\big)$, of least Lipschitz constant exactly $\max\big((1-K_1)^{-1},(1-K_2)^{-1}\big)$.
\end{theorem}

\begin{proof}
Lemma~\ref{lem:sharp} with $a = (1-K_1)^{-1}$, $b = (1-K_2)^{-1}$.
\end{proof}

Thus on the contractive regime forward and inverse certificates are governed by the identical max rule, each attained: laxity is a phenomenon of depth, not of parallelism.

\section{Discussion and future directions}

\subsection{What is rigid and what is not}

The max rule is valid (Theorem~\ref{thm:par}), attained (Theorem~\ref{thm:attain}), minimal among all rules (Theorem~\ref{thm:minimal}), and independent of the product metric (Theorem~\ref{thm:pind}) --- no room for improvement in the single-layer parallel setting. By contrast the calculus is lax, and the laxity compounds exponentially with depth (Theorem~\ref{thm:unbounded}). The rule of thumb: \emph{contract along depth first, take maxima last}.

\subsection{Algorithmic content}

Given a $w\times d$ matrix of certificates, $\sharpg$ costs $O(wd)$ multiplications and $w-1$ comparisons, $\coarseg$ costs $O(wd)$ comparisons and $d-1$ multiplications. Both should be evaluated in log space, where with $\ell_{ij} = \log(1+K_{ij})$,
\[
\log\sharpg = \max_i\sum_j \ell_{ij}, \qquad \log\coarseg = \sum_j\max_i \ell_{ij},
\]
a max-plus computation whose difference is manifestly nonnegative and manifestly maximised when the layer argmaxima are spread across distinct streams.

\subsection{Open problems}

\begin{conjecture}[Extremal laxity defect at arbitrary width]
For a rectangular architecture of width $w$ and depth $d$ with certificates $K_{ij}\in[0,C]$, the defect
\[
\frac{\prod_j\max_i(1+K_{ij})}{\max_i\prod_j(1+K_{ij})}
\]
is maximised by the cyclic architecture $K_{ij} = C\cdot[\,j\equiv i \ (\mathrm{mod}\ w)\,]$, with extremal value $(1+C)^{d(1-1/w)}$; in particular the defect grows to $(1+C)^d$ as the width grows.
\end{conjecture}

The width-two case is settled by Theorems~\ref{thm:sharpcoarse}--\ref{thm:unbounded}; what remains is the combinatorial optimisation over supports in the tropical formulation above.

\begin{conjecture}[Groupoid of contractive residual blocks]
The contractive residual blocks ($K<1$) on a fixed Banach space form a groupoid under serial composition; identify its structure, in particular the least certificate of a composite in terms of the factors and their inverses, and decide whether the inverse operation admits a sharp certificate rule beyond the bound $(1-K)^{-1}$.
\end{conjecture}

Further directions: classify \emph{nonlinear} extremisers (all ours are linear dilations); determine the analogous certificate for genuinely tensorial products of normed spaces (projective or injective tensor norms); study stochastic or averaged parallel structures, where the certificate should interpolate between $\max$ and a $p$-dependent quantity and the invariance of Theorem~\ref{thm:pind} should break in a controlled way; and analyse sharpness when residuals are constrained to a structured class rather than being arbitrary $K$-Lipschitz maps.

